struct ProtocolMessageBuilder {
  typedef ProtocolMessage Table;
  flatbuffers::FlatBufferBuilder &fbb_;
  flatbuffers::uoffset_t start_;
  void add_payload_type(cdda::multiplayer::protocol::MessagePayload payload_type) {
    fbb_.AddElement<uint8_t>(ProtocolMessage::VT_PAYLOAD_TYPE, static_cast<uint8_t>(payload_type), 0);
  }
  void add_payload(flatbuffers::Offset<void> payload) {
    fbb_.AddOffset(ProtocolMessage::VT_PAYLOAD, payload);
  }
  explicit ProtocolMessageBuilder(flatbuffers::FlatBufferBuilder &_fbb)
        : fbb_(_fbb) {
    start_ = fbb_.StartTable();
  }
  ProtocolMessageBuilder &operator=(const ProtocolMessageBuilder &);
  flatbuffers::Offset<ProtocolMessage> Finish() {
    const auto end = fbb_.EndTable(start_);
    auto o = flatbuffers::Offset<ProtocolMessage>(end);
    return o;
  }
};

inline flatbuffers::Offset<ProtocolMessage> CreateProtocolMessage(
    flatbuffers::FlatBufferBuilder &_fbb,
    cdda::multiplayer::protocol::MessagePayload payload_type = cdda::multiplayer::protocol::MessagePayload::NONE,
    flatbuffers::Offset<void> payload = 0) {
  ProtocolMessageBuilder builder_(_fbb);
  builder_.add_payload(payload);
  builder_.add_payload_type(payload_type);
  return builder_.Finish();
}

inline bool VerifyMessagePayload(flatbuffers::Verifier &verifier, const void *obj, MessagePayload type) {
  switch (type) {
    case MessagePayload::NONE: {
      return true;
    }
    case MessagePayload::ClientHello: {
      auto ptr = reinterpret_cast<const cdda::multiplayer::protocol::ClientHello *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessagePayload::ServerHello: {
      auto ptr = reinterpret_cast<const cdda::multiplayer::protocol::ServerHello *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessagePayload::Authenticate: {
      auto ptr = reinterpret_cast<const cdda::multiplayer::protocol::Authenticate *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessagePayload::AuthenticationResult: {
      auto ptr = reinterpret_cast<const cdda::multiplayer::protocol::AuthenticationResult *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessagePayload::ResumeRequest: {
      auto ptr = reinterpret_cast<const cdda::multiplayer::protocol::ResumeRequest *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessagePayload::ResumeResult: {
      auto ptr = reinterpret_cast<const cdda::multiplayer::protocol::ResumeResult *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessagePayload::Ping: {
      auto ptr = reinterpret_cast<const cdda::multiplayer::protocol::Ping *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessagePayload::Pong: {
      auto ptr = reinterpret_cast<const cdda::multiplayer::protocol::Pong *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessagePayload::DisconnectNotice: {
      auto ptr = reinterpret_cast<const cdda::multiplayer::protocol::DisconnectNotice *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessagePayload::PlayerCommand: {
      auto ptr = reinterpret_cast<const cdda::multiplayer::protocol::PlayerCommand *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessagePayload::CommandResult: {
      auto ptr = reinterpret_cast<const cdda::multiplayer::protocol::CommandResult *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessagePayload::SceneSnapshot: {
      auto ptr = reinterpret_cast<const cdda::multiplayer::protocol::SceneSnapshot *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessagePayload::SceneDelta: {
      auto ptr = reinterpret_cast<const cdda::multiplayer::protocol::SceneDelta *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessagePayload::ResyncRequest: {
      auto ptr = reinterpret_cast<const cdda::multiplayer::protocol::ResyncRequest *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessagePayload::ChatMessage: {
      auto ptr = reinterpret_cast<const cdda::multiplayer::protocol::ChatMessage *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

inline bool VerifyMessagePayloadVector(flatbuffers::Verifier &verifier, const flatbuffers::Vector<flatbuffers::Offset<void>> *values, const flatbuffers::Vector<uint8_t> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyMessagePayload(
        verifier,  values->Get(i), types->GetEnum<MessagePayload>(i))) {
      return false;
    }
  }
  return true;
}

inline const cdda::multiplayer::protocol::ProtocolMessage *GetProtocolMessage(const void *buf) {
  return flatbuffers::GetRoot<cdda::multiplayer::protocol::ProtocolMessage>(buf);
}

inline const cdda::multiplayer::protocol::ProtocolMessage *GetSizePrefixedProtocolMessage(const void *buf) {
  return flatbuffers::GetSizePrefixedRoot<cdda::multiplayer::protocol::ProtocolMessage>(buf);
}

inline const char *ProtocolMessageIdentifier() {
  return "CDMP";
}

inline bool ProtocolMessageBufferHasIdentifier(const void *buf) {
  return flatbuffers::BufferHasIdentifier(
      buf, ProtocolMessageIdentifier());
}

inline bool VerifyProtocolMessageBuffer(
    flatbuffers::Verifier &verifier) {
  return verifier.VerifyBuffer<cdda::multiplayer::protocol::ProtocolMessage>(ProtocolMessageIdentifier());
}

inline bool VerifySizePrefixedProtocolMessageBuffer(
    flatbuffers::Verifier &verifier) {
  return verifier.VerifySizePrefixedBuffer<cdda::multiplayer::protocol::ProtocolMessage>(ProtocolMessageIdentifier());
}

inline void FinishProtocolMessageBuffer(
    flatbuffers::FlatBufferBuilder &fbb,
    flatbuffers::Offset<cdda::multiplayer::protocol::ProtocolMessage> root) {
  fbb.Finish(root, ProtocolMessageIdentifier());
}

inline void FinishSizePrefixedProtocolMessageBuffer(
    flatbuffers::FlatBufferBuilder &fbb,
    flatbuffers::Offset<cdda::multiplayer::protocol::ProtocolMessage> root) {
  fbb.FinishSizePrefixed(root, ProtocolMessageIdentifier());
}

